import subprocess, time
def cap():
    return subprocess.run(["tmux","capture-pane","-t","t","-p"],capture_output=True,text=True).stdout
for trial in range(3):
    subprocess.run(["tmux","kill-session","-t","t"],capture_output=True)
    subprocess.run(["tmux","new-session","-d","-s","t","-x","120","-y","40","cd /tmp/proj && /workspace/executable"])
    time.sleep(0.7)
    t0=time.time()
    subprocess.run(["tmux","send-keys","-t","t","C-o"])
    ts=None; te=None
    while time.time()-t0 < 8:
        s=cap()
        if ts is None and "Notification" in s:
            ts=time.time()
        if ts is not None and "Notification" not in s:
            te=time.time(); break
        time.sleep(0.01)
    print("appear:",round((ts-t0)*1000),"duration:",round((te-ts)*1000))
EOF"}

