//! A small single-line text input with readline-like editing.

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use unicode_width::UnicodeWidthChar;

#[derive(Debug, Clone, Default)]
pub struct Input {
    value: String,
    /// Cursor position expressed in characters.
    cursor: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Request {
    InsertChar(char),
    DeletePrevChar,
    DeleteNextChar,
    DeletePrevWord,
    DeleteNextWord,
    DeleteLine,
    DeleteTillEnd,
    GoToPrevChar,
    GoToNextChar,
    GoToPrevWord,
    GoToNextWord,
    GoToStart,
    GoToEnd,
}

/// Result of applying a request: whether the value and/or cursor changed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Change {
    pub value: bool,
    pub cursor: bool,
}

impl Input {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn value(&self) -> &str {
        &self.value
    }

    pub fn reset(&mut self) {
        self.value.clear();
        self.cursor = 0;
    }

    pub fn cursor(&self) -> usize {
        self.cursor
    }

    fn char_count(&self) -> usize {
        self.value.chars().count()
    }

    /// Visual column of the cursor.
    pub fn visual_cursor(&self) -> usize {
        self.value
            .chars()
            .take(self.cursor)
            .map(|c| c.width().unwrap_or(0))
            .sum()
    }

    /// Visual scroll offset so that the cursor fits in `width` columns.
    pub fn visual_scroll(&self, width: usize) -> usize {
        let scroll = self.visual_cursor().max(width) - width;
        let mut uscroll = 0;
        let mut chars = self.value.chars();
        while uscroll < scroll {
            match chars.next() {
                Some(c) => uscroll += c.width().unwrap_or(0),
                None => break,
            }
        }
        uscroll
    }

    /// Convert a key event into an editing request (mirrors common readline bindings).
    pub fn request_for(key: &KeyEvent) -> Option<Request> {
        use KeyCode::*;
        let m = key.modifiers;
        let none = KeyModifiers::NONE;
        let ctrl = KeyModifiers::CONTROL;
        let alt = KeyModifiers::ALT;
        let meta = KeyModifiers::META;
        let shift = KeyModifiers::SHIFT;
        match (key.code, m) {
            (Backspace, mm) if mm == none => Some(Request::DeletePrevChar),
            (Char('h'), mm) if mm == ctrl => Some(Request::DeletePrevChar),
            (Delete, mm) if mm == none => Some(Request::DeleteNextChar),
            (Tab, mm) if mm == none => None,
            (Left, mm) if mm == none => Some(Request::GoToPrevChar),
            (Char('b'), mm) if mm == ctrl => Some(Request::GoToPrevChar),
            (Left, mm) if mm == ctrl => Some(Request::GoToPrevWord),
            (Char('b'), mm) if mm == meta => Some(Request::GoToPrevWord),
            (Right, mm) if mm == none => Some(Request::GoToNextChar),
            (Char('f'), mm) if mm == ctrl => Some(Request::GoToNextChar),
            (Right, mm) if mm == ctrl => Some(Request::GoToNextWord),
            (Char('f'), mm) if mm == meta => Some(Request::GoToNextWord),
            (Char('u'), mm) if mm == ctrl => Some(Request::DeleteLine),
            (Char('w'), mm) if mm == ctrl => Some(Request::DeletePrevWord),
            (Char('d'), mm) if mm == meta => Some(Request::DeletePrevWord),
            (Backspace, mm) if mm == meta || mm == alt => Some(Request::DeletePrevWord),
            (Delete, mm) if mm == ctrl => Some(Request::DeleteNextWord),
            (Char('k'), mm) if mm == ctrl => Some(Request::DeleteTillEnd),
            (Char('a'), mm) if mm == ctrl => Some(Request::GoToStart),
            (Home, mm) if mm == none => Some(Request::GoToStart),
            (Char('e'), mm) if mm == ctrl => Some(Request::GoToEnd),
            (End, mm) if mm == none => Some(Request::GoToEnd),
            (Char(c), mm) if mm == none || mm == shift => Some(Request::InsertChar(c)),
            _ => None,
        }
    }

    pub fn handle_key(&mut self, key: &KeyEvent) -> Option<Change> {
        Self::request_for(key).and_then(|r| self.handle(r))
    }

    pub fn handle(&mut self, req: Request) -> Option<Change> {
        match req {
            Request::InsertChar(c) => {
                let idx = self.byte_index(self.cursor);
                self.value.insert(idx, c);
                self.cursor += 1;
                Some(Change { value: true, cursor: true })
            }
            Request::DeletePrevChar => {
                if self.cursor == 0 {
                    return None;
                }
                self.cursor -= 1;
                let idx = self.byte_index(self.cursor);
                self.value.remove(idx);
                Some(Change { value: true, cursor: true })
            }
            Request::DeleteNextChar => {
                if self.cursor >= self.char_count() {
                    return None;
                }
                let idx = self.byte_index(self.cursor);
                self.value.remove(idx);
                Some(Change { value: true, cursor: false })
            }
            Request::DeletePrevWord => {
                if self.cursor == 0 {
                    return None;
                }
                let chars: Vec<char> = self.value.chars().collect();
                let mut pos = self.cursor;
                // skip whitespace backwards
                while pos > 0 && chars[pos - 1].is_whitespace() {
                    pos -= 1;
                }
                // skip word chars backwards
                while pos > 0 && !chars[pos - 1].is_whitespace() {
                    pos -= 1;
                }
                let new: String = chars[..pos].iter().chain(chars[self.cursor..].iter()).collect();
                self.value = new;
                self.cursor = pos;
                Some(Change { value: true, cursor: true })
            }
            Request::DeleteNextWord => {
                let chars: Vec<char> = self.value.chars().collect();
                if self.cursor >= chars.len() {
                    return None;
                }
                let mut pos = self.cursor;
                while pos < chars.len() && chars[pos].is_whitespace() {
                    pos += 1;
                }
                while pos < chars.len() && !chars[pos].is_whitespace() {
                    pos += 1;
                }
                let new: String = chars[..self.cursor].iter().chain(chars[pos..].iter()).collect();
                self.value = new;
                Some(Change { value: true, cursor: false })
            }
            Request::DeleteLine => {
                if self.value.is_empty() {
                    return None;
                }
                let cursor_changed = self.cursor != 0;
                self.value.clear();
                self.cursor = 0;
                Some(Change { value: true, cursor: cursor_changed })
            }
            Request::DeleteTillEnd => {
                if self.cursor >= self.char_count() {
                    return None;
                }
                let idx = self.byte_index(self.cursor);
                self.value.truncate(idx);
                Some(Change { value: true, cursor: false })
            }
            Request::GoToPrevChar => {
                if self.cursor == 0 {
                    return None;
                }
                self.cursor -= 1;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToNextChar => {
                if self.cursor >= self.char_count() {
                    return None;
                }
                self.cursor += 1;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToPrevWord => {
                if self.cursor == 0 {
                    return None;
                }
                let chars: Vec<char> = self.value.chars().collect();
                let mut pos = self.cursor;
                while pos > 0 && chars[pos - 1].is_whitespace() {
                    pos -= 1;
                }
                while pos > 0 && !chars[pos - 1].is_whitespace() {
                    pos -= 1;
                }
                self.cursor = pos;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToNextWord => {
                let chars: Vec<char> = self.value.chars().collect();
                if self.cursor >= chars.len() {
                    return None;
                }
                let mut pos = self.cursor;
                while pos < chars.len() && chars[pos].is_whitespace() {
                    pos += 1;
                }
                while pos < chars.len() && !chars[pos].is_whitespace() {
                    pos += 1;
                }
                self.cursor = pos;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToStart => {
                if self.cursor == 0 {
                    return None;
                }
                self.cursor = 0;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToEnd => {
                let n = self.char_count();
                if self.cursor == n {
                    return None;
                }
                self.cursor = n;
                Some(Change { value: false, cursor: true })
            }
        }
    }

    fn byte_index(&self, char_idx: usize) -> usize {
        self.value
            .char_indices()
            .nth(char_idx)
            .map(|(i, _)| i)
            .unwrap_or(self.value.len())
    }
}
