                self.cursor = 0;
                Some(Change { value: true, cursor: cursor_changed })
            }
            Request::DeleteTillEnd => {
                if self.cursor >= self.char_count() {
                    return None;
                }
                let idx = self.byte_index(self.cursor);
                self.value.truncate(idx);
                Some(Change { value: true, cursor: false })
            }
            Request::GoToPrevChar => {
                if self.cursor == 0 {
                    return None;
                }
                self.cursor -= 1;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToNextChar => {
                if self.cursor >= self.char_count() {
                    return None;
                }
                self.cursor += 1;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToPrevWord => {
                if self.cursor == 0 {
                    return None;
                }
                let chars: Vec<char> = self.value.chars().collect();
                let mut pos = self.cursor;
                while pos > 0 && chars[pos - 1].is_whitespace() {
                    pos -= 1;
                }
                while pos > 0 && !chars[pos - 1].is_whitespace() {
                    pos -= 1;
                }
                self.cursor = pos;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToNextWord => {
                let chars: Vec<char> = self.value.chars().collect();
                if self.cursor >= chars.len() {
                    return None;
                }
                let mut pos = self.cursor;
                while pos < chars.len() && chars[pos].is_whitespace() {
                    pos += 1;
                }
                while pos < chars.len() && !chars[pos].is_whitespace() {
                    pos += 1;
                }
                self.cursor = pos;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToStart => {
                if self.cursor == 0 {
                    return None;
                }
                self.cursor = 0;
                Some(Change { value: false, cursor: true })
            }
            Request::GoToEnd => {
                let n = self.char_count();
                if self.cursor == n {
                    return None;
                }
                self.cursor = n;
                Some(Change { value: false, cursor: true })
            }
        }
    }

    fn byte_index(&self, char_idx: usize) -> usize {
        self.value
            .char_indices()
            .nth(char_idx)
            .map(|(i, _)| i)
            .unwrap_or(self.value.len())
    }
}
