//! Minimal JSON5 parser producing `serde_json::Value`.

use serde_json::{Map, Number, Value};

#[derive(Debug)]
pub struct ParseError {
    pub line: usize,
    pub col: usize,
    pub expected: String,
}

struct Parser<'a> {
    src: &'a str,
    bytes: &'a [u8],
    pos: usize,
}

pub fn parse(src: &str) -> Result<Value, ParseError> {
    let mut p = Parser { src, bytes: src.as_bytes(), pos: 0 };
    p.skip_ws();
    let v = p.value("array, boolean, null, number, object, or string")?;
    p.skip_ws();
    if p.pos < p.bytes.len() {
        return Err(p.error("EOI"));
    }
    Ok(v)
}

impl<'a> Parser<'a> {
    fn error(&self, expected: &str) -> ParseError {
        let (line, col) = self.line_col(self.pos);
        ParseError { line, col, expected: expected.to_string() }
    }

    fn line_col(&self, pos: usize) -> (usize, usize) {
        let mut line = 1;
        let mut col = 1;
        for (i, ch) in self.src.char_indices() {
            if i >= pos {
                break;
            }
            if ch == '\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        (line, col)
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn skip_ws(&mut self) {
        loop {
            while let Some(c) = self.peek() {
                if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' || c == 0x0b || c == 0x0c {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            // unicode whitespace (nbsp, bom, line/paragraph separators)
            if let Some(ch) = self.src[self.pos..].chars().next() {
                if ch == '\u{a0}' || ch == '\u{feff}' || ch == '\u{2028}' || ch == '\u{2029}' || (ch.is_whitespace() && !ch.is_ascii()) {
                    self.pos += ch.len_utf8();
                    continue;
                }
            }
            if self.bytes[self.pos..].starts_with(b"//") {
                while let Some(c) = self.peek() {
                    if c == b'\n' {
                        break;
                    }
                    self.pos += 1;
                }
                continue;
            }
            if self.bytes[self.pos..].starts_with(b"/*") {
                self.pos += 2;
                while self.pos < self.bytes.len() && !self.bytes[self.pos..].starts_with(b"*/") {
                    self.pos += 1;
                }
                self.pos = (self.pos + 2).min(self.bytes.len());
                continue;
            }
            break;
        }
    }

    fn value(&mut self, expected: &str) -> Result<Value, ParseError> {
        match self.peek() {
            Some(b'{') => self.object(),
            Some(b'[') => self.array(),
            Some(b'"') | Some(b'\'') => Ok(Value::String(self.string()?)),
            Some(c) if c == b'-' || c == b'+' || c == b'.' || c.is_ascii_digit() => self.number(),
            Some(_) => {
                if self.starts_with_word("true") {
                    self.pos += 4;
                    Ok(Value::Bool(true))
                } else if self.starts_with_word("false") {
                    self.pos += 5;
                    Ok(Value::Bool(false))
                } else if self.starts_with_word("null") {
                    self.pos += 4;
                    Ok(Value::Null)
                } else if self.starts_with_word("Infinity") {
                    self.pos += 8;
                    Ok(Value::from(f64::INFINITY))
                } else if self.starts_with_word("NaN") {
                    self.pos += 3;
                    Ok(Value::from(f64::NAN))
                } else {
                    Err(self.error(expected))
                }
            }
            None => Err(self.error(expected)),
        }
    }

    fn starts_with_word(&self, w: &str) -> bool {
        if !self.src[self.pos..].starts_with(w) {
            return false;
        }
        match self.src[self.pos + w.len()..].chars().next() {
            Some(c) if c.is_alphanumeric() || c == '_' || c == '$' => false,
            _ => true,
        }
    }

    fn object(&mut self) -> Result<Value, ParseError> {
        self.pos += 1; // {
        let mut map = Map::new();
        loop {
            self.skip_ws();
            match self.peek() {
                Some(b'}') => {
                    self.pos += 1;
                    return Ok(Value::Object(map));
                }
                None => return Err(self.error("identifier, string, or }")),
                _ => {}
            }
            let key = self.key()?;
            self.skip_ws();
            if self.peek() != Some(b':') {
                return Err(self.error(":"));
            }
            self.pos += 1;
            self.skip_ws();
            let v = self.value("array, boolean, null, number, object, or string")?;
            map.insert(key, v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b'}') => {
                    self.pos += 1;
                    return Ok(Value::Object(map));
                }
                _ => return Err(self.error(", or }")),
            }
        }
    }

    fn key(&mut self) -> Result<String, ParseError> {
        match self.peek() {
            Some(b'"') | Some(b'\'') => self.string(),
            Some(_) => {
                let start = self.pos;
                while let Some(ch) = self.src[self.pos..].chars().next() {
                    if ch.is_alphanumeric() || ch == '_' || ch == '$' || (self.pos == start && ch == '\\') {
                        self.pos += ch.len_utf8();
                    } else {
                        break;
                    }
                }
                if self.pos == start {
                    return Err(self.error("identifier or string"));
                }
                Ok(self.src[start..self.pos].to_string())
            }
            None => Err(self.error("identifier or string")),
        }
    }

    fn array(&mut self) -> Result<Value, ParseError> {
        self.pos += 1; // [
        let mut items = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                Some(b']') => {
                    self.pos += 1;
                    return Ok(Value::Array(items));
                }
                None => return Err(self.error("array, boolean, null, number, object, string, or ]")),
                _ => {}
            }
            let v = self.value("array, boolean, null, number, object, or string")?;
            items.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b']') => {
                    self.pos += 1;
                    return Ok(Value::Array(items));
                }
                _ => return Err(self.error(", or ]")),
            }
        }
    }

    fn string(&mut self) -> Result<String, ParseError> {
        let quote = self.peek().unwrap();
        self.pos += 1;
        let mut out = String::new();
        loop {
            let ch = match self.src[self.pos..].chars().next() {
                Some(c) => c,
                None => return Err(self.error("string terminator")),
            };
            if ch as u32 == quote as u32 {
                self.pos += 1;
                return Ok(out);
            }
            if ch == '\\' {
                self.pos += 1;
                let esc = match self.src[self.pos..].chars().next() {
                    Some(c) => c,
                    None => return Err(self.error("escape sequence")),
                };
                self.pos += esc.len_utf8();
                match esc {
                    'n' => out.push('\n'),
                    't' => out.push('\t'),
                    'r' => out.push('\r'),
                    'b' => out.push('\u{8}'),
                    'f' => out.push('\u{c}'),
                    'v' => out.push('\u{b}'),
                    '0' => out.push('\0'),
                    '\n' => {}
                    '\r' => {
                        if self.peek() == Some(b'\n') {
                            self.pos += 1;
                        }
                    }
                    'x' => {
                        let hex = self.src.get(self.pos..self.pos + 2).unwrap_or("");
                        let v = u32::from_str_radix(hex, 16).map_err(|_| self.error("hex digit"))?;
                        self.pos += 2;
                        out.push(char::from_u32(v).unwrap_or('\u{fffd}'));
                    }
                    'u' => {
                        let hex = self.src.get(self.pos..self.pos + 4).unwrap_or("");
                        let v = u32::from_str_radix(hex, 16).map_err(|_| self.error("hex digit"))?;
                        self.pos += 4;
                        // surrogate pairs
                        if (0xD800..0xDC00).contains(&v) && self.src[self.pos..].starts_with("\\u") {
                            let hex2 = self.src.get(self.pos + 2..self.pos + 6).unwrap_or("");
                            if let Ok(lo) = u32::from_str_radix(hex2, 16) {
                                if (0xDC00..0xE000).contains(&lo) {
                                    self.pos += 6;
                                    let cp = 0x10000 + ((v - 0xD800) << 10) + (lo - 0xDC00);
                                    out.push(char::from_u32(cp).unwrap_or('\u{fffd}'));
                                    continue;
                                }
                            }
                        }
                        out.push(char::from_u32(v).unwrap_or('\u{fffd}'));
                    }
                    other => out.push(other),
                }
                continue;
            }
            if ch == '\n' {
                return Err(self.error("string terminator"));
            }
            out.push(ch);
            self.pos += ch.len_utf8();
        }
    }

    fn number(&mut self) -> Result<Value, ParseError> {
        let start = self.pos;
        let mut sign = 1.0;
        if self.peek() == Some(b'+') {
            self.pos += 1;
        } else if self.peek() == Some(b'-') {
            self.pos += 1;
            sign = -1.0;
        }
        if self.starts_with_word("Infinity") {
            self.pos += 8;
            return Ok(Value::from(sign * f64::INFINITY));
        }
        if self.starts_with_word("NaN") {
            self.pos += 3;
            return Ok(Value::from(f64::NAN));
        }
        if self.bytes[self.pos..].starts_with(b"0x") || self.bytes[self.pos..].starts_with(b"0X") {
            self.pos += 2;
            let hs = self.pos;
            while let Some(c) = self.peek() {
                if c.is_ascii_hexdigit() {
                    self.pos += 1;
                } else {
                    break;
                }
            }
            let v = i64::from_str_radix(&self.src[hs..self.pos], 16).map_err(|_| self.error("hex digit"))?;
            return Ok(Value::Number(Number::from(if sign < 0.0 { -v } else { v })));
        }
        let ds = self.pos;
        let mut is_float = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                self.pos += 1;
            } else if c == b'.' || c == b'e' || c == b'E' {
                is_float = true;
                self.pos += 1;
            } else if (c == b'+' || c == b'-') && is_float {
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.pos == ds {
            self.pos = start;
            return Err(self.error("number"));
        }
        let text = &self.src[ds..self.pos];
        if is_float {
            let mut t = text.to_string();
            if t.starts_with('.') {
                t.insert(0, '0');
            }
            if t.ends_with('.') {
                t.push('0');
            }
            let v: f64 = t.parse().map_err(|_| {
                let (line, col) = self.line_col(start);
                ParseError { line, col, expected: "number".to_string() }
            })?;
            Ok(Value::from(sign * v))
        } else {
            let v: i64 = text.parse().map_err(|_| {
                let (line, col) = self.line_col(start);
                ParseError { line, col, expected: "number".to_string() }
            })?;
            Ok(Value::Number(Number::from(if sign < 0.0 { -v } else { v })))
        }
    }
}

impl ParseError {
    /// Render the error in a pest-like style.
    pub fn render(&self, src: &str, location: &str) -> String {
        let line_text = src.lines().nth(self.line.saturating_sub(1)).unwrap_or("");
        let ln = self.line.to_string();
        let pad = " ".repeat(ln.len());
        let caret_pad = " ".repeat(self.col.saturating_sub(1));
        format!(
            " --> {}:{}\n{} |\n{} | {}\n{} | {}^---\n{} |\n{} = expected {} in {}",
            self.line, self.col, pad, ln, line_text, pad, caret_pad, pad, pad, self.expected, location
        )
    }
}
