//! Configuration loading (keybindings) from the user's config directory.

use std::collections::HashMap;
use std::path::{Path, PathBuf};

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use serde_json::Value;

use crate::json5;

pub const DEFAULT_CONFIG: &str = include_str!("../.config/config.json5");

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    Quit,
    Suspend,
    Refresh,
    LoopOverTabs,
    BackLoopOverTabs,
    ProcessReplace,
    ShowHelp,
    /// Internal actions that may be referenced from a config file but have no effect when bound.
    Noop,
}

impl Action {
    fn parse(s: &str) -> Result<Action, String> {
        Ok(match s {
            "Quit" => Action::Quit,
            "Suspend" => Action::Suspend,
            "Refresh" => Action::Refresh,
            "LoopOverTabs" => Action::LoopOverTabs,
            "BackLoopOverTabs" => Action::BackLoopOverTabs,
            "ProcessReplace" => Action::ProcessReplace,
            "ShowHelp" => Action::ShowHelp,
            "Tick" | "Render" | "Resume" | "ClearScreen" => Action::Noop,
            other => return Err(format!("Unknown Action variant: {other}")),
        })
    }
}

#[derive(Debug, Clone, Default)]
pub struct Config {
    pub keybindings: HashMap<KeyEvent, Action>,
}

/// Panic payload used when a key in the config cannot be parsed (mirrors an `unwrap` on the parse result).
pub struct KeyParsePanic(pub String);

pub fn config_dir() -> PathBuf {
    if let Ok(s) = std::env::var("SERPL_CONFIG") {
        if !s.is_empty() {
            return PathBuf::from(s);
        }
    }
    if let Some(dir) = dirs::config_dir() {
        return dir.join("serpl");
    }
    PathBuf::from(".").join(".config")
}

fn lowercase_keys(v: Value) -> Value {
    match v {
        Value::Object(map) => Value::Object(
            map.into_iter()
                .map(|(k, v)| (k.to_lowercase(), lowercase_keys(v)))
                .collect(),
        ),
        Value::Array(items) => Value::Array(items.into_iter().map(lowercase_keys).collect()),
        other => other,
    }
}

fn merge(base: &mut Value, other: Value) {
    match (base, other) {
        (Value::Object(b), Value::Object(o)) => {
            for (k, v) in o {
                match b.get_mut(&k) {
                    Some(existing) if existing.is_object() && v.is_object() => merge(existing, v),
                    _ => {
                        b.insert(k, v);
                    }
                }
            }
        }
        (b, o) => *b = o,
    }
}

fn relative_display(path: &Path) -> String {
    // Display the path relative to the current directory when possible (as the
    // configuration layer does), falling back to the path itself.
    let cwd = match std::env::current_dir() {
        Ok(c) => c,
        Err(_) => return path.display().to_string(),
    };
    if !path.is_absolute() {
        return path.display().to_string();
    }
    let cwd_comps: Vec<_> = cwd.components().collect();
    let path_comps: Vec<_> = path.components().collect();
    let mut i = 0;
    while i < cwd_comps.len() && i < path_comps.len() && cwd_comps[i] == path_comps[i] {
        i += 1;
    }
    let mut parts: Vec<String> = Vec::new();
    for _ in i..cwd_comps.len() {
        parts.push("..".to_string());
    }
    for c in &path_comps[i..] {
        parts.push(c.as_os_str().to_string_lossy().to_string());
    }
    if parts.is_empty() {
        ".".to_string()
    } else {
        parts.join("/")
    }
}

fn parse_ini(src: &str) -> Value {
    let mut root = serde_json::Map::new();
    let mut section: Option<String> = None;
    for raw in src.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
            continue;
        }
        if line.starts_with('[') && line.ends_with(']') {
            section = Some(line[1..line.len() - 1].trim().to_string());
            continue;
        }
        if let Some(eq) = line.find('=') {
            let key = line[..eq].trim().to_string();
            let mut val = line[eq + 1..].trim().to_string();
            if (val.starts_with('"') && val.ends_with('"') && val.len() >= 2)
                || (val.starts_with('\'') && val.ends_with('\'') && val.len() >= 2)
            {
                val = val[1..val.len() - 1].to_string();
            }
            let target = match &section {
                Some(s) => root
                    .entry(s.clone())
                    .or_insert_with(|| Value::Object(serde_json::Map::new())),
                None => {
                    root.insert(key, Value::String(val));
                    continue;
                }
            };
            if let Value::Object(m) = target {
                m.insert(key, Value::String(val));
            }
        }
    }
    Value::Object(root)
}

fn load_file(path: &Path, format: &str) -> Result<Option<Value>, String> {
    let src = match std::fs::read_to_string(path) {
        Ok(s) => s,
        Err(_) => return Ok(None),
    };
    let location = relative_display(path);
    let value = match format {
        "json5" => json5::parse(&src).map_err(|e| e.render(&src, &location))?,
        "json" => serde_json::from_str::<Value>(&src).map_err(|e| format!("{e} in {location}"))?,
        "yaml" => {
            let y: serde_yaml::Value = serde_yaml::from_str(&src).map_err(|e| format!("{e} in {location}"))?;
            serde_json::to_value(y).map_err(|e| format!("{e} in {location}"))?
        }
        "toml" => {
            let t: toml::Value = toml::from_str(&src).map_err(|e| format!("{e} in {location}"))?;
            serde_json::to_value(t).map_err(|e| format!("{e} in {location}"))?
        }
        "ini" => parse_ini(&src),
        _ => return Ok(None),
    };
    Ok(Some(value))
}

pub fn load() -> Result<Config, String> {
    let mut merged = lowercase_keys(json5::parse(DEFAULT_CONFIG).map_err(|e| e.render(DEFAULT_CONFIG, "default config"))?);
    let dir = config_dir();
    for (file, format) in [
        ("config.json5", "json5"),
        ("config.json", "json"),
        ("config.yaml", "yaml"),
        ("config.toml", "toml"),
        ("config.ini", "ini"),
    ] {
        if let Some(v) = load_file(&dir.join(file), format)? {
            merge(&mut merged, lowercase_keys(v));
        }
    }
    let mut keybindings = HashMap::new();
    if let Some(Value::Object(map)) = merged.get("keybindings") {
        for (k, v) in map {
            let action_name = match v {
                Value::String(s) => s.clone(),
                other => other.to_string(),
            };
            let action = Action::parse(&action_name)?;
            let seq = parse_key_sequence(k);
            match seq {
                Ok(keys) => {
                    if keys.len() == 1 {
                        keybindings.insert(keys[0], action);
                    }
                }
                Err(e) => {
                    std::panic::panic_any(KeyParsePanic(e));
                }
            }
        }
    }
    Ok(Config { keybindings })
}

pub fn parse_key_sequence(raw: &str) -> Result<Vec<KeyEvent>, String> {
    if raw.chars().filter(|c| *c == '>').count() != raw.chars().filter(|c| *c == '<').count() {
        return Err(format!("Unable to parse `{}`", raw));
    }
    let raw = if !raw.contains("><") {
        let raw = raw.strip_prefix('<').unwrap_or(raw);
        let raw = raw.strip_suffix('>').unwrap_or(raw);
        raw
    } else {
        raw
    };
    let sequences = raw
        .split("><")
        .map(|seq| {
            if let Some(s) = seq.strip_prefix('<') {
                s
            } else if let Some(s) = seq.strip_suffix('>') {
                s
            } else {
                seq
            }
        })
        .collect::<Vec<_>>();
    sequences.into_iter().map(parse_key_event).collect()
}

pub fn parse_key_event(raw: &str) -> Result<KeyEvent, String> {
    let raw_lower = raw.to_ascii_lowercase();
    let (remaining, modifiers) = extract_modifiers(&raw_lower);
    parse_key_code_with_modifiers(remaining, modifiers)
}

fn extract_modifiers(raw: &str) -> (&str, KeyModifiers) {
    let mut modifiers = KeyModifiers::empty();
    let mut current = raw;
    loop {
        match current {
            rest if rest.starts_with("ctrl-") => {
                modifiers.insert(KeyModifiers::CONTROL);
                current = &rest[5..];
            }
            rest if rest.starts_with("alt-") => {
                modifiers.insert(KeyModifiers::ALT);
                current = &rest[4..];
            }
            rest if rest.starts_with("shift-") => {
                modifiers.insert(KeyModifiers::SHIFT);
                current = &rest[6..];
            }
            _ => break,
        }
    }
    (current, modifiers)
}

fn parse_key_code_with_modifiers(raw: &str, mut modifiers: KeyModifiers) -> Result<KeyEvent, String> {
    let c = match raw {
        "esc" => KeyCode::Esc,
        "enter" => KeyCode::Enter,
        "left" => KeyCode::Left,
        "right" => KeyCode::Right,
        "up" => KeyCode::Up,
        "down" => KeyCode::Down,
        "home" => KeyCode::Home,
        "end" => KeyCode::End,
        "pageup" => KeyCode::PageUp,
        "pagedown" => KeyCode::PageDown,
        "backtab" => {
            modifiers.insert(KeyModifiers::SHIFT);
            KeyCode::BackTab
        }
        "backspace" => KeyCode::Backspace,
        "delete" => KeyCode::Delete,
        "insert" => KeyCode::Insert,
        "f1" => KeyCode::F(1),
        "f2" => KeyCode::F(2),
        "f3" => KeyCode::F(3),
        "f4" => KeyCode::F(4),
        "f5" => KeyCode::F(5),
        "f6" => KeyCode::F(6),
        "f7" => KeyCode::F(7),
        "f8" => KeyCode::F(8),
        "f9" => KeyCode::F(9),
        "f10" => KeyCode::F(10),
        "f11" => KeyCode::F(11),
        "f12" => KeyCode::F(12),
        "space" => KeyCode::Char(' '),
        "hyphen" => KeyCode::Char('-'),
        "minus" => KeyCode::Char('-'),
        "tab" => KeyCode::Tab,
        c if c.chars().count() == 1 => {
            let mut c = c.chars().next().unwrap();
            if modifiers.contains(KeyModifiers::SHIFT) {
                c = c.to_ascii_uppercase();
            }
            KeyCode::Char(c)
        }
        _ => return Err(format!("Unable to parse {raw}")),
    };
    Ok(KeyEvent::new(c, modifiers))
}
