            SearchMode::Simple => "Simple",
            SearchMode::MatchCase => "Match Case",
            SearchMode::MatchWholeWord => "Match Whole Word",
            SearchMode::MatchCaseWholeWord => "Match Case Whole Word",
            SearchMode::Regex => "Regex",
        }
    }

    fn rg_flags(self) -> &'static [&'static str] {
        match self {
            SearchMode::Simple => &["-i", "-F"],
            SearchMode::MatchCase => &["-s"],
            SearchMode::MatchWholeWord => &["-w", "-i"],
            SearchMode::MatchCaseWholeWord => &["-w", "-s"],
            SearchMode::Regex => &[],
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ReplaceMode {
    #[default]
    Simple,
    PreserveCase,
    DeleteLine,
}

impl ReplaceMode {
    pub fn next(self) -> ReplaceMode {
        match self {
            ReplaceMode::Simple => ReplaceMode::PreserveCase,
            ReplaceMode::PreserveCase => ReplaceMode::DeleteLine,
            ReplaceMode::DeleteLine => ReplaceMode::Simple,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            ReplaceMode::Simple => "Simple",
            ReplaceMode::PreserveCase => "Preserve Case",
            ReplaceMode::DeleteLine => "Delete Line",
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct MatchLine {
    pub line_number: usize,
    /// Line content without the trailing line terminator.
    pub text: String,
    /// Byte ranges (start, end) of the matches within `text`.
    pub submatches: Vec<(usize, usize)>,
    pub before: Vec<String>,
    pub after: Vec<String>,
}

#[derive(Debug, Clone, Default)]
pub struct FileResult {
    /// Path as reported by ripgrep (usable for file operations).
    pub path: String,
    /// Path shown in the result list (project root prefix removed).
    pub display_path: String,
    pub matches: Vec<MatchLine>,
    pub total_matches: usize,
}

/// Whether ripgrep can be executed.
pub fn rg_available() -> bool {
    Command::new("rg")
        .arg("--version")
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .output()
        .is_ok()
}

fn strip_line_terminator(s: &str) -> &str {
    let s = s.strip_suffix('\n').unwrap_or(s);
    s.strip_suffix('\r').unwrap_or(s)
}

fn text_of(v: &Value) -> Option<String> {
    v.get("text").and_then(|t| t.as_str()).map(|s| s.to_string())
}

/// Run ripgrep for `query` in `root` and build the result list.
pub fn run_search(query: &str, mode: SearchMode, root: &str) -> Vec<FileResult> {
    let mut cmd = Command::new("rg");
    cmd.arg("--json").arg("-C").arg("3");
    for f in mode.rg_flags() {
        cmd.arg(f);
    }
    cmd.arg(query).arg(root);
    cmd.stdin(Stdio::null()).stderr(Stdio::null());
    let output = match cmd.output() {
        Ok(o) => o,
        Err(_) => return Vec::new(),
    };
    let stdout = String::from_utf8_lossy(&output.stdout);
    parse_rg_output(&stdout, root)
}

pub fn parse_rg_output(stdout: &str, root: &str) -> Vec<FileResult> {
    let prefix = format!("{}/", root);
    let mut files: Vec<FileResult> = Vec::new();
    let mut current: Option<FileResult> = None;
    // Rolling buffer of the most recent lines seen (shared across files).
    let mut recent: Vec<String> = Vec::new();

    for line in stdout.lines() {
        let v: Value = match serde_json::from_str(line) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let typ = v.get("type").and_then(|t| t.as_str()).unwrap_or("");
        let data = match v.get("data") {
            Some(d) => d,
            None => continue,
        };
        match typ {
            "begin" => {
                let path = data.get("path").and_then(text_of).unwrap_or_default();
                let display_path = path.strip_prefix(prefix.as_str()).unwrap_or(&path).to_string();
                current = Some(FileResult { path, display_path, matches: Vec::new(), total_matches: 0 });
            }
            "match" => {
                let text = data.get("lines").and_then(text_of).unwrap_or_default();
                let text = strip_line_terminator(&text).to_string();
                let line_number = data.get("line_number").and_then(|n| n.as_u64()).unwrap_or(0) as usize;
                let submatches: Vec<(usize, usize)> = data
                    .get("submatches")
                    .and_then(|s| s.as_array())
                    .map(|arr| {
                        arr.iter()
                            .filter_map(|m| {
                                let start = m.get("start")?.as_u64()? as usize;
                                let end = m.get("end")?.as_u64()? as usize;
                                Some((start, end))
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                let m = MatchLine {
                    line_number,
                    text: text.clone(),
                    before: recent.clone(),
                    after: Vec::new(),
                    submatches: submatches.clone(),
                };
                recent.clear();
                recent.push(text);
                if let Some(cur) = current.as_mut() {
                    cur.total_matches += submatches.len();
                    cur.matches.push(m);
                }
            }
            "context" => {
                let text = data.get("lines").and_then(text_of).unwrap_or_default();
                let text = strip_line_terminator(&text).to_string();
                if let Some(cur) = current.as_mut() {
                    if let Some(last) = cur.matches.last_mut() {
                        if last.after.len() < 3 {
                            last.after.push(text.clone());
                        }
                    }
                }
                recent.push(text);
                if recent.len() > 3 {
                    let excess = recent.len() - 3;
                    recent.drain(0..excess);
                }
            }
            "end" => {
                if let Some(cur) = current.take() {
                    if !cur.matches.is_empty() {
                        files.push(cur);
                    }
                }
            }
            _ => {}
        }
    }
    if let Some(cur) = current.take() {
        if !cur.matches.is_empty() {
            files.push(cur);
        }
    }
    files
}
