//! Replacement helpers.

use regex::{NoExpand, Regex};

use crate::search::{FileResult, ReplaceMode, SearchMode};

/// Panic payload used when a file cannot be read or written.
pub struct IoPanic {
    pub message: String,
    pub location: &'static str,
}

/// Build the regex used for replacing text, based on the search mode.
pub fn replace_regex(query: &str, mode: SearchMode) -> Option<Regex> {
    let escaped = regex::escape(query);
    let pattern = match mode {
        SearchMode::MatchCase => escaped,
        SearchMode::MatchWholeWord => format!("(?i)\\b{}\\b", escaped),
        SearchMode::MatchCaseWholeWord => format!("\\b{}\\b", escaped),
        SearchMode::Simple | SearchMode::Regex => format!("(?i){}", escaped),
    };
    Regex::new(&pattern).ok()
}

/// Transform `replacement` so that it follows the casing of `matched`.
pub fn preserve_case(replacement: &str, matched: &str) -> String {
    if !matched.is_empty() && matched.chars().all(|c| c.is_uppercase()) {
        replacement.to_uppercase()
    } else if matched.chars().next().map_or(false, |c| c.is_uppercase()) {
        let mut chars = replacement.chars();
        match chars.next() {
            Some(first) => {
                let mut s: String = first.to_uppercase().collect();
                s.push_str(&chars.as_str().to_lowercase());
                s
            }
            None => String::new(),
        }
    } else {
        replacement.to_lowercase()
    }
}

/// Apply a (non delete-line) replacement to a piece of text.
pub fn replace_text(text: &str, re: &Regex, replacement: &str, mode: ReplaceMode) -> String {
    match mode {
        ReplaceMode::PreserveCase => re
            .replace_all(text, |caps: &regex::Captures| preserve_case(replacement, &caps[0]))
            .into_owned(),
        _ => re.replace_all(text, NoExpand(replacement)).into_owned(),
