//! Application state and event handling.

use std::path::Path;
use std::sync::mpsc::{self, Receiver, Sender};
use std::time::{Duration, Instant};

use crossterm::event::{Event as CEvent, KeyCode, KeyEvent, KeyEventKind, KeyModifiers};

use crate::config::{Action, Config};
use crate::input::Input;
use crate::replace;
use crate::search::{self, FileResult, ReplaceMode, SearchMode};

pub const DEBOUNCE: Duration = Duration::from_millis(300);
pub const NOTIFICATION_DURATION: Duration = Duration::from_secs(3);

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Pane {
    Search,
    Replace,
    SearchResult,
    Preview,
}

impl Pane {
    pub fn next(self) -> Pane {
        match self {
            Pane::Search => Pane::Replace,
            Pane::Replace => Pane::SearchResult,
            Pane::SearchResult => Pane::Search,
            Pane::Preview => Pane::Preview,
        }
    }

    pub fn prev(self) -> Pane {
        match self {
            Pane::Search => Pane::SearchResult,
            Pane::Replace => Pane::Search,
            Pane::SearchResult => Pane::Replace,
            Pane::Preview => Pane::Preview,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Focus {
    Pane(Pane),
    Help,
    Confirm,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConfirmKind {
    EmptyReplace,
    NoGit,
}

impl ConfirmKind {
    pub fn message(self) -> &'static str {
        match self {
            ConfirmKind::EmptyReplace => {
                "Replace text is empty, and replacing with an empty string will remove the matched text."
            }
            ConfirmKind::NoGit => "This action will modify the files in this directory.",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NotificationKind {
    Info,
    Error,
}

#[derive(Debug, Clone)]
pub struct Notification {
    pub message: String,
    pub kind: NotificationKind,
    pub shown_at: Instant,
}

/// Selection state of a vertical list (mirrors a list widget state).
#[derive(Debug, Clone, Copy, Default)]
pub struct ListSel {
    pub offset: usize,
    pub selected: Option<usize>,
}

/// Messages delivered to the main loop from helper threads.
pub enum Msg {
    Term(CEvent),
    DebounceFired(u64),
    SearchDone(u64, Vec<FileResult>),
}

pub struct App {
    pub config: Config,
    pub project_root: String,

    pub search: Input,
    pub search_mode: SearchMode,
    pub replace: Input,
    pub replace_mode: ReplaceMode,

    pub results: Vec<FileResult>,
    pub list: ListSel,

    pub preview: Option<FileResult>,
    pub preview_selected: Option<usize>,
    pub preview_list: ListSel,

    pub active_tab: Pane,
    pub focus: Focus,
    pub help_prev_focus: Focus,

    pub show_help: bool,
    pub help_tab: usize,
    pub show_confirm: bool,
    pub confirm_kind: ConfirmKind,
    /// 0 = Continue, 1 = Cancel
    pub confirm_selected: usize,

    pub notification: Option<Notification>,

    pub should_quit: bool,
    pub should_suspend: bool,
    pub should_clear: bool,

    search_seq: u64,
    tx: Sender<Msg>,
}

impl App {
    pub fn new(config: Config, project_root: String, tx: Sender<Msg>) -> Self {
        Self {
            config,
            project_root,
            search: Input::new(),
            search_mode: SearchMode::Simple,
            replace: Input::new(),
            replace_mode: ReplaceMode::Simple,
            results: Vec::new(),
            list: ListSel::default(),
            preview: None,
            preview_selected: None,
            preview_list: ListSel::default(),
            active_tab: Pane::Search,
            focus: Focus::Pane(Pane::Search),
            help_prev_focus: Focus::Pane(Pane::Search),
            show_help: false,
            help_tab: 0,
            show_confirm: false,
            confirm_kind: ConfirmKind::EmptyReplace,
            confirm_selected: 1,
            notification: None,
            should_quit: false,
            should_suspend: false,
            should_clear: false,
            search_seq: 0,
            tx,
        }
    }

    pub fn is_focused(&self, pane: Pane) -> bool {
        self.focus == Focus::Pane(pane)
    }

    pub fn status_text(&self) -> &'static str {
        match self.focus {
            Focus::Pane(Pane::Search) => "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>",
            Focus::Pane(Pane::Replace) => "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>",
            Focus::Pane(Pane::SearchResult) => {
                "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"
            }
            Focus::Pane(Pane::Preview) => {
                "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete line: <d>"
            }
            Focus::Help => "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>",
            Focus::Confirm => "Confirm Replace: <Enter> | Cancel Replace: <Esc>, Left: <h>, Right: <l>, Loop: <Tab>",
        }
    }

    pub fn notify(&mut self, message: impl Into<String>, kind: NotificationKind) {
        self.notification = Some(Notification { message: message.into(), kind, shown_at: Instant::now() });
    }

    pub fn expire_notification(&mut self) {
        if let Some(n) = &self.notification {
            if n.shown_at.elapsed() >= NOTIFICATION_DURATION {
                self.notification = None;
            }
        }
    }

    // ----- searching -------------------------------------------------------

    fn schedule_search(&mut self) {
        self.search_seq += 1;
        let seq = self.search_seq;
        let tx = self.tx.clone();
        std::thread::spawn(move || {
            std::thread::sleep(DEBOUNCE);
            let _ = tx.send(Msg::DebounceFired(seq));
        });
    }

    fn start_search(&mut self) {
        let query = self.search.value().to_string();
        if query.is_empty() {
            return;
        }
        self.search_seq += 1;
        let seq = self.search_seq;
        self.results.clear();
        self.list = ListSel::default();
        let mode = self.search_mode;
        let root = self.project_root.clone();
        let tx = self.tx.clone();
        std::thread::spawn(move || {
            let results = search::run_search(&query, mode, &root);
            let _ = tx.send(Msg::SearchDone(seq, results));
        });
    }

    pub fn handle_msg(&mut self, msg: Msg) {
        match msg {
            Msg::Term(ev) => self.handle_term_event(ev),
            Msg::DebounceFired(seq) => {
                if seq == self.search_seq {
                    self.start_search();
                }
            }
            Msg::SearchDone(seq, results) => {
                if seq == self.search_seq {
                    self.results = results;
                    self.list = ListSel::default();
                }
            }
        }
    }

    fn handle_term_event(&mut self, ev: CEvent) {
        match ev {
            CEvent::Key(key) => {
                if key.kind == KeyEventKind::Release {
                    return;
                }
                self.handle_key(key);
            }
            CEvent::Resize(_, _) => {}
            _ => {}
        }
    }

    // ----- key handling ----------------------------------------------------

    fn handle_key(&mut self, key: KeyEvent) {
        // Keys are first offered to the focused component, then to the global keymap.
        let lookup = KeyEvent::new(key.code, key.modifiers);
        let action = self.config.keybindings.get(&lookup).copied();

        match self.focus {
            Focus::Help if self.show_help => self.help_key(key),
            Focus::Confirm if self.show_confirm => self.confirm_key(key),
            Focus::Pane(Pane::Search) => self.search_key(key),
            Focus::Pane(Pane::Replace) => self.replace_key(key),
            Focus::Pane(Pane::SearchResult) => self.list_key(key),
            Focus::Pane(Pane::Preview) => self.preview_key(key),
            _ => {}
        }

        if let Some(action) = action {
            self.handle_action(action);
        }
    }

    fn handle_action(&mut self, action: Action) {
        match action {
            Action::Quit => self.should_quit = true,
            Action::Suspend => self.should_suspend = true,
            Action::Refresh => self.should_clear = true,
            Action::ShowHelp => {
                self.help_prev_focus = self.focus;
                self.focus = Focus::Help;
                self.show_help = true;
                self.show_confirm = false;
            }
            Action::ProcessReplace => self.process_replace(),
            Action::LoopOverTabs => {
                if !self.show_help && !self.show_confirm {
                    self.active_tab = self.active_tab.next();
                    self.focus = Focus::Pane(self.active_tab);
                }
            }
            Action::BackLoopOverTabs => {
                if !self.show_help && !self.show_confirm {
                    self.active_tab = self.active_tab.prev();
                    self.focus = Focus::Pane(self.active_tab);
                }
            }
            Action::Noop => {}
        }
    }

    fn is_ctrl(key: &KeyEvent, c: char) -> bool {
        key.modifiers == KeyModifiers::CONTROL && key.code == KeyCode::Char(c)
    }

    fn search_key(&mut self, key: KeyEvent) {
        if Self::is_ctrl(&key, 'n') {
            self.search_mode = self.search_mode.next();
            self.preview = self.results.first().cloned();
            self.start_search();
            return;
        }
        if key.code == KeyCode::Enter {
            if !self.search.value().is_empty() {
                self.schedule_search();
            }
            return;
        }
        if let Some(change) = self.search.handle_key(&key) {
            if change.value && !self.search.value().is_empty() {
                self.schedule_search();
            }
        }
    }

    fn replace_key(&mut self, key: KeyEvent) {
        if Self::is_ctrl(&key, 'n') {
            self.replace_mode = self.replace_mode.next();
            return;
        }
        if key.code == KeyCode::Enter {
            return;
        }
        if self.replace_mode != ReplaceMode::DeleteLine {
            self.replace.handle_key(&key);
        }
    }

    fn set_preview_from_list(&mut self) {
        self.preview = self.list.selected.and_then(|i| self.results.get(i).cloned());
    }

    fn list_key(&mut self, key: KeyEvent) {
        let len = self.results.len();
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => {
                if len == 0 {
                    return;
                }
                let next = match self.list.selected {
                    Some(i) if i + 1 < len => i + 1,
                    Some(_) => 0,
                    None => 0,
                };
                self.list.selected = Some(next);
                self.set_preview_from_list();
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if len == 0 {
                    return;
                }
                let prev = match self.list.selected {
                    Some(0) | None => len - 1,
                    Some(i) => i - 1,
                };
                self.list.selected = Some(prev);
                self.set_preview_from_list();
            }
            KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                if len == 0 {
                    return;
                }
                self.list.selected = Some(0);
                self.set_preview_from_list();
            }
            KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                if len == 0 {
                    return;
                }
                self.list.selected = Some(len - 1);
                self.set_preview_from_list();
            }
            KeyCode::Enter => {
                self.active_tab = Pane::Preview;
                self.focus = Focus::Pane(Pane::Preview);
            }
            KeyCode::Char('d') => {
                if let Some(i) = self.list.selected {
                    if i < len {
                        self.results.remove(i);
                        self.clamp_list_selection();
                        self.set_preview_from_list();
                    }
                }
            }
            KeyCode::Char('r') => {
                if let Some(i) = self.list.selected {
                    if i < len {
                        let file = self.results[i].clone();
                        replace::replace_in_file(
                            &file,
                            self.search.value(),
                            self.search_mode,
                            self.replace.value(),
                            self.replace_mode,
                        );
                        self.results.remove(i);
                        self.clamp_list_selection();
                        self.notify("File replacement completed successfully", NotificationKind::Info);
                    }
                }
            }
            _ => {}
        }
    }

    fn clamp_list_selection(&mut self) {
        if self.results.is_empty() {
            self.list.selected = None;
        } else if let Some(i) = self.list.selected {
            if i >= self.results.len() {
                self.list.selected = Some(self.results.len() - 1);
            }
        }
    }

    /// Row index (within the flattened preview rows) of the match line of match `idx`.
    pub fn preview_row_of(&self, idx: usize) -> usize {
        let mut row = 0;
        if let Some(p) = &self.preview {
            for (i, m) in p.matches.iter().enumerate() {
                if i == idx {
                    return row + m.before.len();
                }
                row += m.before.len() + 1 + m.after.len() + 1;
            }
        }
        row
    }

    fn preview_len(&self) -> usize {
        self.preview.as_ref().map(|p| p.matches.len()).unwrap_or(0)
    }

    fn select_preview(&mut self, idx: usize) {
        self.preview_selected = Some(idx);
        self.preview_list.selected = Some(self.preview_row_of(idx));
    }

    fn preview_key(&mut self, key: KeyEvent) {
        let len = self.preview_len();
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => {
                if len == 0 {
                    return;
                }
                let next = match self.preview_selected {
                    Some(i) if i + 1 < len => i + 1,
                    Some(_) => 0,
                    None => 0,
                };
                self.select_preview(next);
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if len == 0 {
                    return;
                }
                let prev = match self.preview_selected {
                    Some(0) | None => len - 1,
                    Some(i) if i >= len => len - 1,
                    Some(i) => i - 1,
                };
                self.select_preview(prev);
            }
            KeyCode::Char('g') | KeyCode::Char('h') | KeyCode::Left => {
                if len == 0 {
                    return;
                }
                self.select_preview(0);
            }
            KeyCode::Char('G') | KeyCode::Char('l') | KeyCode::Right => {
                if len == 0 {
                    return;
                }
                self.select_preview(len - 1);
            }
            KeyCode::Enter | KeyCode::Esc => {
                self.active_tab = Pane::SearchResult;
                self.focus = Focus::Pane(Pane::SearchResult);
            }
            KeyCode::Char('d') => {
                let (Some(li), Some(mi)) = (self.list.selected, self.preview_selected) else { return };
                let Some(file) = self.results.get_mut(li) else { return };
                if mi >= file.matches.len() {
                    return;
                }
                file.matches.remove(mi);
                file.total_matches = file.total_matches.saturating_sub(1);
                self.preview_selected = Some(mi.saturating_sub(1));
                self.after_line_removed(li);
            }
            KeyCode::Char('r') => {
                let (Some(li), Some(mi)) = (self.list.selected, self.preview_selected) else { return };
                let Some(file) = self.results.get(li) else { return };
                if mi >= file.matches.len() {
                    return;
                }
                let path = file.path.clone();
                let line_number = file.matches[mi].line_number;
                replace::replace_line_in_file(
                    &path,
                    line_number,
                    self.search.value(),
                    self.search_mode,
                    self.replace.value(),
                    self.replace_mode,
                );
                let file = &mut self.results[li];
                file.matches.remove(mi);
                file.total_matches = file.total_matches.saturating_sub(1);
                self.after_line_removed(li);
                self.notify("Line replacement completed successfully", NotificationKind::Info);
            }
            _ => {}
        }
    }

    fn after_line_removed(&mut self, li: usize) {
        if self.results[li].matches.is_empty() {
            self.results.remove(li);
            self.clamp_list_selection();
        }
        self.set_preview_from_list();
    }

    fn help_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('q') | KeyCode::Esc => {
                self.show_help = false;
                self.focus = self.help_prev_focus;
            }
            KeyCode::Right | KeyCode::Char('l') | KeyCode::Tab => {
                self.help_tab = (self.help_tab + 1) % 2;
            }
            KeyCode::Left | KeyCode::Char('h') => {
                self.help_tab = (self.help_tab + 2 - 1) % 2;
            }
            KeyCode::Char('1') => self.help_tab = 0,
            KeyCode::Char('2') => self.help_tab = 1,
            _ => {}
        }
    }

    fn confirm_key(&mut self, key: KeyEvent) {
        match key.code {
            KeyCode::Char('h') | KeyCode::Char('l') | KeyCode::Left | KeyCode::Right | KeyCode::Tab | KeyCode::BackTab => {
                self.confirm_selected = (self.confirm_selected + 1) % 2;
            }
            KeyCode::Enter => {
                if self.confirm_selected == 0 {
                    self.replace_all();
                } else {
                    self.show_confirm = false;
                }
            }
            KeyCode::Esc => {
                self.show_confirm = false;
            }
            _ => {}
        }
    }

    // ----- replacing -------------------------------------------------------

    fn process_replace(&mut self) {
        if self.search.value().is_empty() {
            self.notify("Search text cannot be empty", NotificationKind::Error);
            return;
        }
        self.show_help = false;
        if self.replace.value().is_empty() {
            self.confirm_kind = ConfirmKind::EmptyReplace;
            self.show_confirm = true;
            self.focus = Focus::Confirm;
            return;
        }
        if !Path::new(&self.project_root).join(".git").exists() {
            self.confirm_kind = ConfirmKind::NoGit;
            self.show_confirm = true;
            self.focus = Focus::Confirm;
            return;
        }
        self.replace_all();
    }

    fn replace_all(&mut self) {
        let files = self.results.clone();
        for file in &files {
            replace::replace_in_file(
                file,
                self.search.value(),
                self.search_mode,
                self.replace.value(),
                self.replace_mode,
            );
        }
        self.reset_after_replace();
        self.notify("Search and replace completed successfully", NotificationKind::Info);
    }

    fn reset_after_replace(&mut self) {
        // Invalidate any in-flight search.
        self.search_seq += 1;
        self.search.reset();
        self.search_mode = SearchMode::Simple;
        self.replace.reset();
        self.replace_mode = ReplaceMode::Simple;
        self.results.clear();
        self.list = ListSel::default();
        self.preview = None;
        self.preview_selected = None;
        self.preview_list = ListSel::default();
        self.show_confirm = false;
        self.show_help = false;
        self.active_tab = Pane::Search;
        self.focus = Focus::Pane(Pane::Search);
    }
}

/// Spawn the thread that forwards terminal events to the main loop.
pub fn spawn_input_thread(tx: Sender<Msg>) {
    std::thread::spawn(move || loop {
        match crossterm::event::read() {
            Ok(ev) => {
                if tx.send(Msg::Term(ev)).is_err() {
                    break;
                }
            }
            Err(_) => {
                std::thread::sleep(Duration::from_millis(10));
            }
        }
    });
}

pub fn channel() -> (Sender<Msg>, Receiver<Msg>) {
    mpsc::channel()
}
