/// A styled piece of text in a preview row.
struct Seg {
    text: String,
    style: Style,
}

fn seg(text: impl Into<String>, style: Style) -> Seg {
    Seg { text: text.into(), style }
}

fn build_preview_rows(app: &App, inner_width: usize) -> Vec<Vec<Seg>> {
    let mut rows: Vec<Vec<Seg>> = Vec::new();
    let Some(file) = &app.preview else { return rows };
    let replacement = app.replace.value();
    let ctx_num = Style::default().fg(Color::Blue);
    let ctx_text = Style::default().fg(Color::DarkGray);
    let match_num = Style::default().fg(Color::LightGreen);
    for (i, m) in file.matches.iter().enumerate() {
        let n = m.before.len();
        for (k, b) in m.before.iter().enumerate() {
            let num = m.line_number.saturating_sub(n - k);
            rows.push(vec![seg(format!("{:>4} ", num), ctx_num), seg(b.clone(), ctx_text)]);
        }
        let mut row = vec![seg(format!("{:>4} ", m.line_number), match_num)];
        if app.replace_mode == ReplaceMode::DeleteLine {
            row.push(seg(
                m.text.clone(),
                Style::default().fg(Color::White).bg(Color::Red).add_modifier(Modifier::CROSSED_OUT),
            ));
        } else {
            let text = m.text.as_str();
            let mut last = 0usize;
            for &(s, e) in &m.submatches {
                let s = s.min(text.len());
                let e = e.min(text.len()).max(s);
                if s < last {
                    continue;
                }
                if !text.is_char_boundary(s) || !text.is_char_boundary(e) {
                    continue;
                }
                if s > last {
                    row.push(seg(&text[last..s], Style::default()));
                }
                let matched = &text[s..e];
                if replacement.is_empty() {
                    row.push(seg(matched, Style::default().bg(Color::Blue)));
                } else {
                    row.push(seg(
                        matched,
                        Style::default().fg(Color::White).bg(Color::LightRed).add_modifier(Modifier::CROSSED_OUT),
                    ));
                    let rep = match app.replace_mode {
                        ReplaceMode::PreserveCase => preserve_case(replacement, matched),
                        _ => replacement.to_string(),
                    };
                    row.push(seg(rep, Style::default().fg(Color::White).bg(Color::Green)));
                }
                last = e;
            }
            if last < text.len() {
                row.push(seg(&text[last..], Style::default()));
            }
        }
        rows.push(row);
        for (k, a) in m.after.iter().enumerate() {
            rows.push(vec![seg(format!("{:>4} ", m.line_number + k + 1), ctx_num), seg(a.clone(), ctx_text)]);
        }
        let sep_style = match app.preview_selected {
            Some(sel) if i <= sel => Style::default().fg(Color::Yellow),
            _ => Style::default().fg(Color::DarkGray),
        };
        rows.push(vec![seg("─".repeat(inner_width), sep_style)]);
    }
    rows
}

/// Write a string into the buffer one grapheme at a time (control characters are kept).
fn put_str(buf: &mut Buffer, x: u16, y: u16, max_width: u16, text: &str, style: Style) -> u16 {
    let mut remaining = buf.area.right().saturating_sub(x).min(max_width);
    let mut x = x;
    for g in UnicodeSegmentation::graphemes(text, true) {
        let width = g.width() as u16;
        if width == 0 {
            continue;
        }
        if width > remaining {
            break;
        }
        remaining -= width;
        if let Some(cell) = buf.cell_mut((x, y)) {
            cell.set_symbol(g);
            cell.set_style(style);
        }
        let next = x + width;
        x += 1;
        while x < next {
            if let Some(cell) = buf.cell_mut((x, y)) {
                cell.reset();
            }
            x += 1;
        }
    }
    x
}

/// Render the preview rows as a list with a selectable row (mirrors a list widget).
fn render_rows(buf: &mut Buffer, area: Rect, rows: &[Vec<Seg>], state: &mut ListSel, highlight: Style) {
    if area.width == 0 || area.height == 0 {
        return;
    }
    if rows.is_empty() {
        state.selected = None;
        return;
    }
    if let Some(s) = state.selected {
        if s >= rows.len() {
            state.selected = Some(rows.len() - 1);
        }
    }
    let max_height = area.height as usize;
    let mut offset = state.offset.min(rows.len() - 1);
    if let Some(sel) = state.selected {
        if sel >= offset + max_height {
            offset = sel + 1 - max_height;
        }
        if sel < offset {
            offset = sel;
        }
    }
    state.offset = offset;
    let selection_spacing = state.selected.is_some();
    let symbol_width: u16 = if selection_spacing { 2 } else { 0 };
    for (i, row) in rows.iter().enumerate().skip(offset).take(max_height) {
        let y = area.y + (i - offset) as u16;
        let row_area = Rect::new(area.x, y, area.width, 1);
        let is_selected = state.selected == Some(i);
        let mut x = area.x + symbol_width.min(area.width);
        let mut remaining = area.width.saturating_sub(symbol_width);
        for s in row {
            if remaining == 0 {
                break;
            }
            let nx = put_str(buf, x, y, remaining, &s.text, s.style);
            remaining = remaining.saturating_sub(nx - x);
            x = nx;
        }
        if selection_spacing {
            let symbol = if is_selected { "> " } else { "  " };
            put_str(buf, area.x, y, area.width, symbol, Style::default());
        }
        if is_selected {
            buf.set_style(row_area, highlight);
        }
    }
}

fn draw_preview(frame: &mut Frame, app: &mut App, area: Rect) {
    let border_style = if app.is_focused(Pane::Preview) {
        Style::default().fg(Color::Green)
    } else {
        Style::default()
    };
    let block = rounded_block(border_style).title(Line::from("Preview"));
    let inner = block.inner(area);
    frame.render_widget(block, area);
    let rows = build_preview_rows(app, inner.width as usize);
    let highlight = Style::default().fg(Color::White).add_modifier(Modifier::BOLD);
    let mut state = app.preview_list;
    render_rows(frame.buffer_mut(), inner, &rows, &mut state, highlight);
    app.preview_list = state;
}

fn draw_status(frame: &mut Frame, app: &App, area: Rect) {
    let [left, _right] = Layout::horizontal([Constraint::Percentage(70), Constraint::Percentage(30)]).areas(area);
    let paragraph = Paragraph::new(app.status_text())
        .style(Style::default().fg(Color::Blue))
        .wrap(Wrap { trim: true });
    frame.render_widget(paragraph, left);
}

fn centered_rect(width: u16, height: u16, r: Rect) -> Rect {
    let w = width.min(r.width);
    let h = height.min(r.height);
    let x = r.x + (r.width - w) / 2;
    let y = r.y + (r.height - h) / 2;
    Rect::new(x, y, w, h)
}

/// Shared dialog skeleton: clears the area, styles the body and returns (inner, text_area, footer_row).
fn dialog_areas(area: Rect) -> (Rect, Rect, Rect) {
    let inner = Rect::new(
        area.x.saturating_add(1),
        area.y.saturating_add(1),
        area.width.saturating_sub(2),
        area.height.saturating_sub(2),
    );
    let body = Rect::new(inner.x, inner.y, inner.width, inner.height.saturating_sub(1));
    let text = Rect::new(
        inner.x.saturating_add(1),
        inner.y.saturating_add(1),
        inner.width.saturating_sub(2),
        inner.height.saturating_sub(4),
    );
    let footer = Rect::new(inner.x, inner.y + inner.height.saturating_sub(1), inner.width, 2);
    (body, text, footer)
}

fn draw_help(frame: &mut Frame, app: &App, area: Rect) {
    let dialog = centered_rect(80, 15, area);
    frame.render_widget(Clear, dialog);
    let (body, text_area, _footer) = dialog_areas(dialog);
    let yellow = Style::default().fg(Color::Yellow);
    let green = Style::default().fg(Color::Green);

    frame.buffer_mut().set_style(body, Style::default().fg(Color::White));
    let items = if app.help_tab == 0 { HELP_GLOBAL } else { HELP_NAVIGATION };
    let lines: Vec<Line> = items.iter().map(|s| Line::from(*s)).collect();
    let paragraph = Paragraph::new(lines).wrap(Wrap { trim: false });
    frame.render_widget(paragraph, text_area);

    let tab_style = |i: usize| if app.help_tab == i { green } else { yellow };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(yellow)
        .title(Line::from(Span::styled(" [1] Global ", tab_style(0))))
        .title(Line::from(Span::styled(" [2] Navigation ", tab_style(1))))
        .title(Line::from(Span::styled("Press 'q' to close", yellow)).alignment(Alignment::Right));
    frame.render_widget(block, dialog);
}

fn draw_confirm(frame: &mut Frame, app: &App, area: Rect) {
    let message = app.confirm_kind.message();
    let width = (message.chars().count() + 4) as u16;
    let dialog = centered_rect(width, 8, area);
    frame.render_widget(Clear, dialog);
    let (body, text_area, footer) = dialog_areas(dialog);
    let yellow = Style::default().fg(Color::Yellow);

    frame.buffer_mut().set_style(body, Style::default().fg(Color::White));
    let paragraph = Paragraph::new(vec![Line::from(message), Line::from("Are you sure you want to continue?")])
        .alignment(Alignment::Center)
        .wrap(Wrap { trim: true });
    frame.render_widget(paragraph, text_area);

    // Buttons
    let labels = [" Continue ", " Cancel "];
    let total: u16 = labels.iter().map(|l| l.chars().count() as u16).sum();
    let mut x = footer.x + footer.width.saturating_sub(total) / 2;
    for (i, label) in labels.iter().enumerate() {
        let w = label.chars().count() as u16;
        let style = if app.confirm_selected == i {
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::White)
        };
        let btn_area = Rect::new(x, footer.y, w, footer.height).intersection(frame.area());
        frame.render_widget(Paragraph::new(*label).style(style), btn_area);
        x += w;
    }
    let _ = ConfirmKind::EmptyReplace;

    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(yellow)
        .title(Line::from(Span::styled("Confirm Dialog", yellow)).alignment(Alignment::Center));
    frame.render_widget(block, dialog);
}

fn draw_notification(frame: &mut Frame, app: &App, area: Rect) {
    let Some(n) = &app.notification else { return };
    let color = match n.kind {
        NotificationKind::Info => Color::Blue,
        NotificationKind::Error => Color::Red,
    };
    let width = (n.message.chars().count() as u16).wrapping_add(4);
    let height: u16 = 3;
    let x = area.width.wrapping_sub(width).wrapping_sub(1);
    let y = area.height.wrapping_sub(height).wrapping_sub(2);
    if x >= area.width || y >= area.height {
        std::panic::panic_any(BufferPanic {
            message: format!(
                "index outside of buffer: the area is Rect {{ x: 0, y: 0, width: {}, height: {} }} but index is ({}, {})",
                area.width, area.height, x, y
            ),
            location: "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/ratatui-0.29.0/src/buffer/buffer.rs:253".to_string(),
        });
    }
    let rect = Rect::new(x, y, width, height).intersection(area);
    frame.render_widget(Clear, rect);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .border_style(Style::default().fg(color).add_modifier(Modifier::BOLD))
        .title_style(Style::default().fg(color).add_modifier(Modifier::BOLD))
        .title(Line::from("Notification"));
    let paragraph = Paragraph::new(n.message.clone()).style(Style::default().fg(color)).block(block);
    frame.render_widget(paragraph, rect);
}

