fn write_crash_report(message: &str, file: &str, line: u32) -> Option<String> {
    let path = std::env::temp_dir().join(format!("report-{}.toml", random_uuid()));
    let content = format!(
        "name = \"{PKG_NAME}\"\noperating_system = \"{}\"\ncrate_version = \"{PKG_VERSION}\"\nexplanation = \"\"\"\nPanic occurred in file '{file}' at line {line}\n\"\"\"\ncause = '{}'\nmethod = \"Panic\"\nbacktrace = \"\"\"\n\n   0:        0x0 - <unresolved>\"\"\"",
        os_description(),
        message.replace('\'', "\\'")
    );
    std::fs::write(&path, content).ok()?;
    Some(path.display().to_string())
}

fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        tui::restore_on_panic();
        let payload = info.payload();
        let (message, location): (String, String) = if let Some(p) = payload.downcast_ref::<replace::IoPanic>() {
            (p.message.clone(), p.location.to_string())
        } else if let Some(p) = payload.downcast_ref::<tui::BufferPanic>() {
            (p.message.clone(), p.location.clone())
        } else if let Some(p) = payload.downcast_ref::<config::KeyParsePanic>() {
            (
                format!("called `Result::unwrap()` on an `Err` value: {:?}", p.0),
                "src/config.rs:94".to_string(),
            )
        } else {
            let msg = if let Some(s) = payload.downcast_ref::<&str>() {
                s.to_string()
            } else if let Some(s) = payload.downcast_ref::<String>() {
                s.clone()
            } else {
                "Box<dyn Any>".to_string()
            };
            let loc = info
                .location()
                .map(|l| format!("{}:{}", l.file(), l.line()))
                .unwrap_or_else(|| "<unknown>".to_string());
            (msg, loc)
        };
        let (file, line) = match location.rsplit_once(':') {
            Some((f, l)) => (f.to_string(), l.parse::<u32>().unwrap_or(0)),
            None => (location.clone(), 0),
        };
        let report = write_crash_report(&message, &file, line).unwrap_or_else(|| "<unknown>".to_string());
        let mut err = io::stderr();
        let color = err.is_terminal();
        let human = format!(
            "Well, this is embarrassing.\n\n{PKG_NAME} had a problem and crashed. To help us diagnose the problem you can send us a crash report.\n\nWe have generated a report file at \"{report}\". Submit an issue or email with the subject of \"{PKG_NAME} Crash Report\" and include the report as an attachment.\n\n- Authors: {AUTHORS}\n\nWe take privacy seriously, and do not perform any automated error collection. In order to improve the software, we rely on people to submit reports.\n\nThank you kindly!\n"
        );
        if color {
            let _ = write!(err, "\x1b[31m{human}\x1b[0m");
        } else {
            let _ = write!(err, "{human}");
        }
        let _ = write!(
            err,
            "\x1b[31mThe application panicked (crashed).\x1b[0m\nMessage:  \x1b[36m{message}\x1b[0m\nLocation: \x1b[35m{file}\x1b[0m:\x1b[35m{line}\x1b[0m\n\nThis is a bug. Consider reporting it at {REPOSITORY}\n"
        );
        let _ = err.flush();
        std::process::exit(1);
    }));
}

fn main() {
    if !search::rg_available() {
        eprintln!("\x1b[31mError: ripgrep (rg) is not installed. Please install it to use {PKG_NAME}.\x1b[0m");
        eprintln!("{PKG_NAME} error: Something went wrong");
        eprintln!("Error: ripgrep is not installed\n\nLocation:\n    src/main.rs:42:16");
        std::process::exit(1);
    }

    let matches = Command::new(PKG_NAME)
        .version(version_string())
        .author(AUTHORS)
        .about("A simple terminal UI for search and replace, ala VS Code")
        .arg(
            Arg::new("project_root")
                .short('p')
                .long("project-root")
                .value_name("PATH")
                .default_value(".")
                .help("Path to the project root"),
        )
        .get_matches();
    let project_root = matches.get_one::<String>("project_root").cloned().unwrap_or_else(|| ".".to_string());

    install_panic_hook();

    let config = match config::load() {
        Ok(c) => c,
        Err(e) => fail(&e),
    };

    if let Err(e) = run(config, project_root) {
        fail(&e);
    }
}

fn run(config: config::Config, project_root: String) -> Result<(), String> {
    let (tx, rx) = app::channel();
    let mut app = App::new(config, project_root, tx.clone());

    tui::enter().map_err(|e| e.to_string())?;
    let backend = CrosstermBackend::new(io::stdout());
    let mut terminal = Terminal::new(backend).map_err(|e| {
        let _ = tui::exit();
        e.to_string()
    })?;
    terminal.clear().map_err(|e| e.to_string())?;

    app::spawn_input_thread(tx.clone());

    let frame_duration = Duration::from_secs_f64(1.0 / FRAME_RATE);
    let mut next_frame = Instant::now();
    let result = loop {
        let now = Instant::now();
        if now >= next_frame {
            app.expire_notification();
            if app.should_clear {
                app.should_clear = false;
                if let Err(e) = terminal.clear() {
                    break Err(e.to_string());
                }
            }
            if let Err(e) = terminal.draw(|f| ui::draw(f, &mut app)) {
                break Err(e.to_string());
            }
            while next_frame <= now {
                next_frame += frame_duration;
            }
        }
        if app.should_quit {
            break Ok(());
        }
        if app.should_suspend {
            app.should_suspend = false;
            if let Err(e) = tui::exit() {
                break Err(e.to_string());
            }
            unsafe {
                libc::raise(libc::SIGTSTP);
            }
            if let Err(e) = tui::enter() {
                break Err(e.to_string());
            }
            if let Err(e) = terminal.clear() {
                break Err(e.to_string());
            }
            continue;
        }
        let timeout = next_frame.saturating_duration_since(Instant::now());
        match rx.recv_timeout(timeout) {
            Ok(msg) => {
                app.handle_msg(msg);
                // Drain anything else that is immediately available.
                while let Ok(msg) = rx.try_recv() {
                    app.handle_msg(msg);
                }
            }
            Err(RecvTimeoutError::Timeout) => {}
            Err(RecvTimeoutError::Disconnected) => break Ok(()),
        }
    };

    let _ = tui::exit();
    result
}
