/// Render a line into `rect`, truncating it to the rect width.
fn render_title_line(buf: &mut Buffer, rect: Rect, line: &Line) {
    let rect = rect.intersection(buf.area);
    if rect.is_empty() {
        return;
    }
    let mut x = rect.x;
    let mut remaining = rect.width;
    for span in &line.spans {
        if remaining == 0 {
            break;
        }
        let style = line.style.patch(span.style);
        let nx = put_str(buf, x, rect.y, remaining, &span.content, style);
        remaining = remaining.saturating_sub(nx - x);
        x = nx;
    }
}

/// Render a rounded block with titles. Titles are drawn right, then center, then left so that
/// left titles win when they overlap (matching the behaviour the application was built with).
fn render_block(buf: &mut Buffer, area: Rect, border_style: Style, left: &[Line], center: Option<&Line>, right: Option<&Line>) {
    use ratatui::widgets::Widget;
    rounded_block(border_style).render(area, buf);
    if area.width < 2 || area.height == 0 {
        return;
    }
    let titles_area = Rect::new(area.x + 1, area.y, area.width - 2, 1);
    if let Some(r) = right {
        let w = r.width() as u16;
        let x = titles_area.right().saturating_sub(w).max(titles_area.left());
        let rect = Rect::new(x, titles_area.y, w.min(titles_area.width), 1);
        buf.set_style(rect, border_style);
        render_title_line(buf, rect, r);
