    if let Some(c) = center {
        let w = c.width() as u16;
        let x = titles_area.left() + titles_area.width.saturating_sub(w) / 2;
        let rect = Rect::new(x, titles_area.y, w.min(titles_area.width), 1);
        buf.set_style(rect, border_style);
        render_title_line(buf, rect, c);
    }
    let mut ta = titles_area;
